package e.e.a;
import android.app.Service;import android.content.Context;import android.preference.PreferenceManager;import android.view.*;import android.widget.*;
public final class PopupGestures {
 public static final String KEY="popup_double_tap_seek";
 static boolean enabled(Context c){return PreferenceManager.getDefaultSharedPreferences(c).getBoolean(KEY,false);}
 public static boolean doubleTap(Object object,MotionEvent event){Service c=(Service)object;if(!enabled(c))return false;try{if(event.getPointerCount()!=1)return true;Object player=object.getClass().getField("e").get(object);if(!(player instanceof View))return true;View video=(View)player;int[] at=new int[2];video.getLocationOnScreen(at);if(event.getRawY()<at[1]||event.getRawY()>at[1]+video.getHeight())return true;int side=event.getRawX()<at[0]+video.getWidth()/2f?-1:1;int seconds=Integer.parseInt(PreferenceManager.getDefaultSharedPreferences(c).getString("double_tap_seek_seconds","10"));if(seconds<=0)return true;long position=((Number)player.getClass().getMethod("getCurrentPosition").invoke(player)).longValue(),duration=((Number)player.getClass().getMethod("getDuration").invoke(player)).longValue();if(duration>0){player.getClass().getMethod("seekTo",long.class).invoke(player,SeekRules.target(position,duration,side,seconds));Toast.makeText(c,(side>0?"+":"−")+seconds+" s",0).show();}}catch(Exception e){android.util.Log.w("nicoid-popup","Cannot seek popup",e);}return true;}
 public static void attach(Object object,View root){Service c=(Service)object;if(!enabled(c)||root.findViewWithTag("popup-close")!=null)return;View menu=root.findViewById(c.getResources().getIdentifier("topmenulay","id",c.getPackageName()));if(!(menu instanceof RelativeLayout))return;View close=new View(c);PlayerIcons.symbol(close,"close");close.setContentDescription("ポップアップ再生を終了");close.setTag("popup-close");close.setId(View.generateViewId());close.setOnClickListener(v->c.stopSelf());RelativeLayout.LayoutParams p=new RelativeLayout.LayoutParams(PanelUi.dp(c,44),PanelUi.dp(c,44));p.addRule(RelativeLayout.ALIGN_PARENT_RIGHT);p.addRule(RelativeLayout.ALIGN_PARENT_TOP);((RelativeLayout)menu).addView(close,p);View fullscreen=root.findViewById(c.getResources().getIdentifier("fullscbutton","id",c.getPackageName()));if(fullscreen!=null&&fullscreen.getLayoutParams() instanceof RelativeLayout.LayoutParams){RelativeLayout.LayoutParams fp=(RelativeLayout.LayoutParams)fullscreen.getLayoutParams();fp.removeRule(RelativeLayout.ALIGN_PARENT_RIGHT);fp.addRule(RelativeLayout.LEFT_OF,close.getId());fullscreen.setLayoutParams(fp);}PopupOverlay.attach(root);}
}
